class GymMember {private static int count=0;private final String membershipNumber;private int monthlyFee,paid;public GymMember(int fee){if(fee<=0)throw new IllegalArgumentException("Fee must be positive");monthlyFee=fee;membershipNumber="GYM-"+(2000+(++count));}public String getMembershipNumber(){return membershipNumber;}public void payFee(int amount){if(amount<0)throw new IllegalArgumentException("Negative payment");paid+=amount;}public void payFee(int amount,String mode){System.out.println("Payment mode: "+mode);payFee(amount);}public int getFeesPaid(){return paid;}public static int getMembersEnrolled(){return count;}}
class GroupClassMember extends GymMember {private String className;public GroupClassMember(int fee,String c){super(fee);className=c;}}
public class GymMembershipAuditMain {
 public static boolean isValidReferralCode(String s){return s!=null&&s.length()==4&&s.charAt(0)=='G'&&Character.isDigit(s.charAt(1))&&Character.isDigit(s.charAt(2))&&Character.isUpperCase(s.charAt(3));}
 public static String processWeeklyCheckIn(GymMember[] ms){int done=0,nulls=0,groups=0,individuals=0;for(GymMember m:ms){if(m==null){nulls++;continue;}done++;if(m instanceof GroupClassMember)groups++;else individuals++;}return done+" processed | "+nulls+" null skipped | "+groups+" group | "+individuals+" individual";}
 public static void main(String[] a){GymMember m=new GymMember(1000);System.out.println(m.getMembershipNumber());System.out.println(getCount());System.out.println(isValidReferralCode("G45B"));m.payFee(500);m.payFee(500,"UPI");System.out.println(m.getFeesPaid());System.out.println(processWeeklyCheckIn(new GymMember[]{new GroupClassMember(1500,"Zumba"),null,new GymMember(1000)}));}
 private static int getCount(){return GymMember.getMembersEnrolled();}
}
